DOMAIN_PLATFORM = {
1: "RHEL-family kernels may carry vendor backports and ABI/support commitments; Debian/Ubuntu releases package their kernel and user space on their own lifecycle. A distribution combines kernel and user-space components rather than being the kernel alone.",
2: "GNU coreutils/grep options are not universal on BusyBox/minimal images; Bash may be absent or `/bin/sh` may be dash/ash. Verify interpreter and utility versions before depending on flags.",
3: "RHEL-family commonly enforces SELinux, while Ubuntu commonly enables AppArmor; both still use DAC. PAM/NSS/SSSD and OpenSSH defaults depend on release and identity integration.",
4: "Current RHEL and Debian/Ubuntu releases commonly use systemd, but unit files, packaged defaults, journal persistence and legacy SysV compatibility differ. Read the installed merged unit.",
5: "PSI, perf/eBPF capabilities and sysstat tools depend on kernel config/version and distro packages. Install or enable tooling only through supported package and policy workflows.",
6: "RHEL storage guidance commonly covers XFS/LVM; Debian/Ubuntu deployments may use ext4 or other layouts. Filesystem grow/repair tooling and cloud-volume contracts differ; verify exact support.",
7: "NetworkManager is common on RHEL; Ubuntu may use Netplan with NetworkManager or systemd-networkd. firewalld/UFW are frontends, while nftables is the kernel rules framework.",
8: "SELinux is central on RHEL-family systems and AppArmor common on Ubuntu; package-signing, audit, Secure Boot and baseline tooling have release-specific procedures.",
9: "The running kernel and distribution/runtime determine cgroup v1/v2, delegation, rootless support and default seccomp/LSM profile. Never infer effective limits from config intent alone.",
10: "Cloud-init stages, datasource detection, agents and disk/interface naming differ by provider and image. A custom AMI or Ubuntu cloud image may not behave like a local VM of the same distro.",
11: "Pacemaker/Corosync, fencing agents, support contracts and cloud zone/region guarantees are platform-specific; validate the exact supported combination and failure model.",
12: "Journal persistence, syslog routing, auditd and diagnostic utilities vary with release and configured retention. Preserve logs through approved, access-controlled incident channels.",
13: "A supported RHEL/Ubuntu/Amazon Linux offering and a community-compatible derivative can have different patch escalation and lifecycle commitments; assign ownership for each layer.",
14: "Console recovery, snapshot tooling, command options and package names vary by release/provider; prove the recovery route on the disposable target before a disruptive exercise.",
}

DOMAIN_CAUTION = {
1: "Do not infer support or patch state from a kernel version string, install packages from an untrusted repository, or edit boot configuration without a console and tested recovery path.",
2: "Do not run unreviewed downloaded code as root, hide pipeline failures, or apply broad file transformations before testing filenames and inputs in a disposable fixture.",
3: "Do not use broad recursive permission changes, disable host-key checking, or directly edit identity databases to bypass an access failure.",
4: "Do not force-kill or reboot before preserving relevant process and boot evidence; do not assume restart and reload have the same semantics.",
5: "Do not tune from a single metric snapshot or copy generic sysctl values; profiling and eBPF need bounded scope, authorization and overhead review.",
6: "Do not partition, format, repair, resize, alter RAID/LVM or delete data outside an isolated lab and separately approved change with verified backups.",
7: "Do not flush/change routes, firewall, resolver or interface settings on a remote host without out-of-band access and a tested rollback.",
8: "Do not disable SELinux/AppArmor, expose private keys/secrets, or run an opaque hardening script as a substitute for policy diagnosis.",
9: "Do not grant privileged-container access, expose the host runtime socket, or treat namespaces alone as a security boundary.",
10: "Do not embed secrets in user data/images or roll untested configuration across a fleet; retain a known-good artifact and canary stop condition.",
11: "Do not call a design highly available without testing failover, fencing/state consistency, measured recovery and failure-domain independence.",
12: "Do not restart/kill processes or discard logs before assessing transient evidence, write consistency and customer impact.",
13: "Do not use production credentials/data in capstones or claim readiness without repeatable evidence, failure handling and rollback.",
14: "Do not use production systems or devices containing needed data as a lab; destructive/disruptive work requires explicit approval, isolation and proven recovery.",
}

def make_guide(objective, domain, ordinal, lesson, role_label, references):
    concept, practice, scenario, commands = lesson
    first, *remaining = concept.split(". ")
    first = first.rstrip(".")
    mechanics = ". ".join(remaining).strip()
    if mechanics and not mechanics.endswith("."):
        mechanics += "."
    if not mechanics:
        mechanics = f"The operator decision is to follow this distinction in the target release and verify the observed behavior: {practice}"

    platform_detail = DOMAIN_PLATFORM[domain]
    distro_line = f"**Distro/release distinction:** {platform_detail} Record the exact distribution, release and relevant tool/kernel version when using this outcome as a fleet standard; do not transfer defaults between image families."
    role_prefix = f"**Role extension:** {role_label}. This checklist outcome extends, rather than duplicates, the shared technical domains.\n\n" if role_label else ""
    command_lines = "\n".join(f"{line.strip()}" for line in commands.split("; "))
    code_note = "Inspection/validation examples; replace angle-bracket placeholders with a reviewed target. Options and tool availability vary by release; review output for secrets before sharing."
    if domain in (7, 8):
        code_note += " Packet capture or security/audit output requires authorization and controlled handling."
    if domain == 14:
        code_note += " These examples collect evidence only; they do not authorize the lab action."

    first_command = commands.split(";")[0].strip()
    q1 = f"**Q: What technical distinction changes the decision for this objective?**\n\nA: {first}."
    q2 = f"**Q: In this scenario, what should be inspected before intervention?**\n\nA: Start with `{first_command}`. {practice}"
    q3 = f"**Q: What would count as evidence that the objective is met in this case?**\n\nA: {scenario} Confirm the relevant state described here: {mechanics}"

    return f"""# {objective}

**Syllabus objective (exact wording):** {objective}

{role_prefix}**Mapping:** `{domain:02d}` → `{ordinal:03d}` `{objective}`

## What

{concept}

## Why

This matters operationally: {scenario} The decision hinges on these mechanics: {mechanics}

## How

1. **Establish the relevant boundary:** {first}. Confirm the target release and actual service/process context before selecting the check.
2. **Apply the operator method:** {practice}
3. **Exercise the scenario:** {scenario}
4. **Verify this outcome:** inspect `{first_command}` and check specifically for the state that distinguishes this objective: {first}. Compare the result with the scenario's expected behavior before proposing a change.
5. **Choose a response:** apply the supported action in the operator method only when that evidence supports it; if the result contradicts the scenario, stop and revise the hypothesis.

## Features

**Technical mechanics:** {mechanics}

{distro_line}

**Failure mode or decision risk:** {scenario} Avoid this domain-specific hazard: {DOMAIN_CAUTION[domain]}

## Code snippets (if any)

{code_note}

```sh
{command_lines}
```

## Do's and Don'ts

- **Do:** {practice}
- **Don't:** {DOMAIN_CAUTION[domain]}
- **Lab-only:** destructive or disruptive operations mentioned by this objective must be tested only on disposable systems unless a separately approved production change includes verified backup, impact review and rollback.

## Real life implementation

**Scenario:** {scenario}

**Implementation:** {practice} Capture `{first_command}` output and the scenario's service, storage, identity, policy or recovery result as appropriate. For any disruptive step, use a disposable lab and retain rollback evidence.

## Q&A

{q1}

{q2}

{q3}

## References

{references}
"""


def main():
    objectives = [line[6:].strip() for line in SYLLABUS.read_text(encoding="utf-8").splitlines() if line.startswith("- [ ] ")]
    expected_counts = {1: 9, 2: 10, 3: 9, 4: 10, 5: 10, 6: 13, 7: 11, 8: 13, 9: 9, 10: 8, 11: 9, 12: 8, 13: 15, 14: 12}
    if len(objectives) != 146:
        raise SystemExit(f"Expected 146 checkboxes; found {len(objectives)}.")
    if any(len(LESSONS.get(domain, [])) != count for domain, count in expected_counts.items()):
        raise SystemExit({domain: len(LESSONS.get(domain, [])) for domain in expected_counts})

    seen = set()
    updated = 0
    for path in ROOT.glob("[0-9][0-9]-*/**/study-guide.md"):
        text = path.read_text(encoding="utf-8")
        mapping = re.search(r"^\*\*Mapping:\*\* `(\d+)`.*?→ `(\d+)` `?(.+?)`?$", text, re.M)
        if not mapping:
            raise SystemExit(f"Missing mapping in {path}")
        domain, ordinal, objective = int(mapping.group(1)), int(mapping.group(2)), mapping.group(3).strip().rstrip("`")
        if objective not in objectives or objective in seen:
            raise SystemExit(f"Invalid or duplicate objective mapping in {path}: {objective}")
        seen.add(objective)
        role_match = re.search(r"^\*\*Role extension:\*\* ([^.]+)\.", text, re.M)
        role_label = role_match.group(1) if role_match else ""
        refs_match = re.search(r"^## References\n\n(.+)$", text, re.M | re.S)
        references = refs_match.group(1).strip() if refs_match else "[Linux kernel documentation](https://docs.kernel.org/) · [Linux man-pages project](https://www.kernel.org/doc/man-pages/) · [Syllabus](../../../copilot-Linux-syllabus.md)"
        path.write_text(make_guide(objective, domain, ordinal, LESSONS[domain][ordinal - 1], role_label, references), encoding="utf-8", newline="\n")
        updated += 1
    if updated != 146 or seen != set(objectives):
        raise SystemExit(f"Updated {updated}; coverage {len(seen)}/146.")
    print(f"Upgraded {updated} objective-specific guides.")


if __name__ == "__main__":
    main()
